/// The texts of the places in French, by place id.
const placeTextsFr = <String, PlaceText>{
  'must_see_burj-khalifa': PlaceText(
    name: 'Burj Khalifa',
    description: 'Le Burj Khalifa est un chef-d’œuvre d’architecture et le plus haut bâtiment du monde, qui s’élève à l’incroyable hauteur de 828 mètres au-dessus du cœur de Dubaï. Sa silhouette élancée et effilée s’inspire de l’architecture islamique, tandis que son ingénierie représente le summum de l’innovation moderne. Les visiteurs peuvent découvrir ses ascenseurs ultrarapides et ses plateformes d’observation de renommée mondiale aux niveaux 124, 125 et 148, et profiter de vues panoramiques qui s’étendent sur la ville, le littoral et le vaste désert au-delà. Entouré par la Fontaine de Dubaï et des attractions de luxe, le Burj Khalifa n’est pas seulement une construction qui bat des records : c’est aussi un symbole de l’ambition, de la créativité et de la vision futuriste de Dubaï.',
